"""Client commands: thin wrappers over the HTTP API (R16)."""
from __future__ import annotations

import http.client
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

TIMEOUT = 10


def _dump(obj):
    return json.dumps(obj, separators=(",", ":"), ensure_ascii=True) + "\n"


def _usage(message):
    sys.stderr.write("linkvault: %s\n" % message)
    return 2


def _build(args):
    """Return (method, path, headers, body) for the parsed command."""
    command = args.command
    if command == "token":
        return "POST", "/v1/tokens", {"X-Admin-Key": args.admin_key}, b"{}"
    if command == "shorten":
        payload = {"url": args.url}
        if args.slug is not None:
            payload["slug"] = args.slug
        if args.expires_in is not None:
            payload["expires_in"] = args.expires_in
        return "POST", "/v1/links", {"Content-Type": "application/json"}, _dump(payload).encode("utf-8")
    if command == "list":
        return "GET", "/v1/links", {}, None
    path = "/v1/links/" + urllib.parse.quote(args.slug, safe="")
    return ("DELETE" if command == "delete" else "GET"), path, {}, None


def run(args):
    server = args.server or os.environ.get("LINKVAULT_SERVER")
    token = args.token or os.environ.get("LINKVAULT_TOKEN")
    if not server:
        return _usage("no server given (use --server or LINKVAULT_SERVER)")
    if args.command != "token" and not token:
        return _usage("no token given (use --token or LINKVAULT_TOKEN)")
    server = server.rstrip("/")
    try:
        parts = urllib.parse.urlsplit(server)
        if parts.scheme not in ("http", "https") or not parts.hostname:
            raise ValueError("expected http(s)://host[:port]")
        parts.port  # raises ValueError for a bad port
        method, path, headers, body = _build(args)
        if args.command != "token":
            headers["Authorization"] = "Bearer " + token
        request = urllib.request.Request(server + path, data=body, headers=headers, method=method)
    except ValueError as exc:
        return _usage("invalid server URL %r: %s" % (server, exc))

    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    try:
        try:
            with opener.open(request, timeout=TIMEOUT) as resp:
                status, raw = resp.status, resp.read()
        except urllib.error.HTTPError as exc:  # before URLError (its superclass)
            with exc:
                raw = exc.read()
            try:
                sys.stderr.write(_dump(json.loads(raw)))
            except ValueError:
                sys.stderr.write("linkvault: HTTP %d: %s\n" % (exc.code, raw.decode("utf-8", "replace")))
            return 1
    except (urllib.error.URLError, OSError, http.client.HTTPException) as exc:
        sys.stderr.write("linkvault: connection failed: %s\n" % exc)
        return 3
    except ValueError as exc:  # e.g. invalid URL detected while connecting
        return _usage("invalid server URL %r: %s" % (server, exc))

    if status == 204:
        return 0
    try:
        out = _dump(json.loads(raw))
    except ValueError:
        sys.stderr.write("linkvault: server returned a non-JSON response\n")
        return 3
    sys.stdout.write(out)
    return 0
